def to256(box, margin=8):
    x0,y0,x1,y1 = box
    return [max(0,x0+16-margin), max(0,y0+16-margin), min(256,x1+16+margin), min(256,y1+16+margin)]
def mirror_fill(img, box):
    """Remove content of box by reflecting neighbouring pixels into it (horizontal or vertical, whichever has more context)."""
    x0,y0,x1,y1 = box; H,W,_ = img.shape; w = x1-x0; h = y1-y0
    out = img.copy()
    horiz = (W-w)/max(w,1) >= (H-h)/max(h,1)
    if horiz:
        L = img[y0:y1, :x0]; R = img[y0:y1, x1:]
        nl = int(round(w*L.shape[1]/max(L.shape[1]+R.shape[1],1))); nr = w-nl
        if L.shape[1]==0: nl, nr = 0, w
        if R.shape[1]==0: nl, nr = w, 0
        if nl>0: out[y0:y1, x0:x0+nl] = np.pad(L, ((0,0),(0,nl),(0,0)), mode='symmetric')[:, L.shape[1]:L.shape[1]+nl]
        if nr>0: out[y0:y1, x1-nr:x1] = np.pad(R, ((0,0),(nr,0),(0,0)), mode='symmetric')[:, :nr]
    else:
        T = img[:y0, x0:x1]; Bm = img[y1:, x0:x1]
        nt = int(round(h*T.shape[0]/max(T.shape[0]+Bm.shape[0],1))); nb = h-nt
        if T.shape[0]==0: nt, nb = 0, h
        if Bm.shape[0]==0: nt, nb = h, 0
        if nt>0: out[y0:y0+nt, x0:x1] = np.pad(T, ((0,nt),(0,0),(0,0)), mode='symmetric')[T.shape[0]:T.shape[0]+nt]
        if nb>0: out[y1-nb:y1, x0:x1] = np.pad(Bm, ((nb,0),(0,0),(0,0)), mode='symmetric')[:nb]
    return out
